KEYS.extend(COMPLIANCE_KEYS)
for code in P:
    P[code].extend(COMPLIANCE_KEYS[key][code] for key in COMPLIANCE_KEYS)

assert len(P) == 21
assert all(len(v) == len(KEYS) for v in P.values()), {k: len(v) for k, v in P.items()}

NAMES = [("en-US","English"),("de-DE","Deutsch"),("fr-FR","Français"),
         ("es-ES","Español"),("it-IT","Italiano"),("tr-TR","Türkçe"),
         ("pt-PT","Português"),("hu-HU","Magyar"),("nb-NO","Norsk"),
         ("sv-SE","Svenska"),("nl-NL","Nederlands"),("cs-CZ","Čeština"),
         ("pl-PL","Polski"),("ru-RU","Русский"),("zh-CN","简体中文"),
         ("zh-HK","繁體中文"),("ja-JP","日本語"),("ko-KR","한국어"),
         ("vi-VN","Tiếng Việt"),("id-ID","Bahasa Indonesia"),("th-TH","ไทย")]

out = ['/* NetCheck i18n: 21 complete language packs (key parity build-checked). */',
       '"use strict";', 'const LOCALES = [']
out += [f'  ["{c}","{n}"],' for c, n in NAMES]
out.append('];')
out.append('const I18N = {')
for code, vals in P.items():
    out.append(f'"{code}": {{')
    out.append(",".join(f'\n  "{k}":{json.dumps(v, ensure_ascii=False)}'
                        for k, v in zip(KEYS, vals)))
    out.append('\n},')
out.append('};')
out.append('''// Browser-language resolution chain: exact -> variant map -> unique prefix -> en-US
const LANG_VARIANTS = {
  "zh-tw":"zh-HK","zh-hant":"zh-HK","zh-mo":"zh-HK","zh-sg":"zh-CN","zh-hans":"zh-CN",
  "en-gb":"en-US","en-au":"en-US","en-ca":"en-US","en-nz":"en-US","en-za":"en-US","en-in":"en-US",
  "fr-ca":"fr-FR","fr-be":"fr-FR","fr-ch":"fr-FR","de-at":"de-DE","de-ch":"de-DE",
  "pt-br":"pt-PT","es-mx":"es-ES","es-ar":"es-ES","es-cl":"es-ES","es-co":"es-ES",
  "nb":"nb-NO","no":"nb-NO","nn":"nb-NO","id":"id-ID","vi":"vi-VN","th":"th-TH",
}
function resolveBrowserLang(candidates) {
  const list = (candidates && candidates.length ? candidates : [navigator.language]) || [];
  for (const raw of list) {
    const tag = String(raw || "").trim();
    if (!tag) continue;
    if (I18N[tag]) return tag;
    const lower = tag.toLowerCase();
    if (LANG_VARIANTS[lower] && I18N[LANG_VARIANTS[lower]]) return LANG_VARIANTS[lower];
    const base = lower.split("-")[0];
    if (LANG_VARIANTS[base] && I18N[LANG_VARIANTS[base]]) return LANG_VARIANTS[base];
    const byPrefix = Object.keys(I18N).filter(k => k.toLowerCase().startsWith(base + "-"));
    if (byPrefix.length === 1) return byPrefix[0];
  }
  return "en-US";
}
let curLang = localStorage.getItem("nc-lang") || resolveBrowserLang(navigator.languages);
function t(key, ...values){
  const pack = I18N[curLang] || I18N["en-US"];
  let text = pack[key] !== undefined ? pack[key]
       : (I18N["en-US"][key] !== undefined ? I18N["en-US"][key] : key);
  values.forEach((value, index) => {
    text = text.split(`{${index + 1}}`).join(String(value));
  });
  return text;
}
function setLang(code){
  curLang = code; localStorage.setItem("nc-lang", code);
  document.documentElement.lang = code;
}''')

dest = os.path.join(os.path.dirname(__file__), "..", "assets", "i18n.js")
if os.path.exists(dest):
    with open(dest, encoding="utf-8") as existing:
        current = existing.read()
    if '"ar-SA"' in current and os.environ.get("NETCHECK_FORCE_I18N") != "1":
        raise SystemExit(
            "refusing to overwrite the 23-pack shipping asset "
            "(webui/assets/i18n.js contains ar-SA and the RTL packs). "
            "Patch it directly, or set NETCHECK_FORCE_I18N=1 to regenerate "
            "the 21-pack baseline and restore the RTL packs afterwards.")
with open(dest, "w", encoding="utf-8") as f:
    f.write("\n".join(out) + "\n")
print(f"generated {dest}: {len(P)} packs x {len(KEYS)} keys, "
      f"{os.path.getsize(dest)} bytes")
